-- =====================================================================
-- Phase 1 生产触达配置（自动生成，请勿手改）
-- 生成器：scripts/config/gen-phase1-config-sql.py
-- 来源：渠道模板清单与配置 §4.1/§5.1/§7 · 渠道编排规格 §7.4~§7.9
-- 依赖：db/schema.sql + db/schema-admin.sql
-- 用法：mysql -h<host> -P<port> -u<user> -p ai_collection_db < db/seed-phase1-config.sql
-- 幂等：按 script_slot / template_code 先删后建
-- =====================================================================

SET @TENANT = 'mocasa-ph';
SET @CFG_VER = 2;
SET @OPERATOR = 'seed-phase1-config';

START TRANSACTION;

-- 旧的 delayMin 模板（SEED_%）是 L4 联调节奏：所有步骤相隔 1 分钟，
-- 在生产会让同一客户 3 分钟内连收 3 条。必须整体替换为 dayBlocks 绝对槽位。
DELETE FROM t_strategy_rule    WHERE tenant_id = @TENANT AND rule_name LIKE 'SEED\_%';
DELETE FROM t_contact_plan_template WHERE tenant_id = @TENANT AND template_code LIKE 'SEED\_%';
DELETE FROM t_contact_plan_template WHERE tenant_id = @TENANT AND template_code LIKE 'PH1\_%';

DELETE FROM t_script_template WHERE tenant_id = @TENANT AND script_slot IN (
    'S0_DUE_TODAY', 'S0_DUE_TODAY_EMAIL', 'S0_REMINDER', 'S0_REMINDER_URGENT', 'S1_EMAIL_OVERDUE_NOTICE', 'S1_PUSH_STANDARD', 'S1_SMS_STANDARD', 'S2_EMAIL_ENTRY', 'S2_PUSH_STANDARD', 'S2_SMS_FIRM', 'S2_SMS_STANDARD', 'S3_PUSH_STANDARD', 'S3_SMS_FIRM', 'S3_SMS_STANDARD', 'S4_EMAIL_ENTRY', 'S4_EMAIL_PRE_CLOSE', 'S4_PUSH_STANDARD', 'S4_SMS_FIRM', 'S4_SMS_STANDARD'
);

-- 文案槽位：SMS 10 + Push 7 + Email 5。缺任意一条，Resolver 会跳过该步骤不发送，
