-- Stage → plan 模板路由（DPD 区间对齐编排规格 §4.1；D+91 起停催，不建计划）
INSERT INTO t_strategy_rule
    (tenant_id, rule_name, priority, match_dpd_min, match_dpd_max, output_template_id, output_tone, status, config_version, version, created_by, updated_by)
SELECT @TENANT, CONCAT('PH1_', stage, '_RULE'), 100,
       CASE stage WHEN 'S0' THEN -3 WHEN 'S1' THEN 1 WHEN 'S2' THEN 4 WHEN 'S3' THEN 16 WHEN 'S4' THEN 31 END,
       CASE stage WHEN 'S0' THEN 0 WHEN 'S1' THEN 3 WHEN 'S2' THEN 15 WHEN 'S3' THEN 30 WHEN 'S4' THEN 90 END,
       id, 'STANDARD', 'ACTIVE', @CFG_VER, 0, @OPERATOR, @OPERATOR
FROM t_contact_plan_template
WHERE tenant_id = @TENANT AND template_code LIKE 'PH1\_%';

UPDATE t_config_version_seq SET current_version = GREATEST(current_version, @CFG_VER), updated_at = NOW() WHERE id = 1;

INSERT INTO t_config_change_log
    (tenant_id, config_type, config_key, from_version, to_version, diff_summary, operator, reason, created_at)
VALUES
    (@TENANT, 'plan_template', 'phase1-dayblocks', 1, @CFG_VER,
     JSON_OBJECT('summary', 'Replace delayMin integration cadence with PHT dayBlocks; complete all 17 SMS/Push slots'),
     @OPERATOR, 'seed-phase1-config.sql', NOW());

COMMIT;

-- 自检：三个 count 必须分别等于 10 / 7 / 5，plan_templates 等于 5
SELECT 'SEED_PHASE1_CONFIG_OK' AS result,
       (SELECT COUNT(*) FROM t_script_template WHERE tenant_id = @TENANT AND channel = 'SMS'   AND status = 'ACTIVE') AS sms_slots,   -- expect 10
       (SELECT COUNT(*) FROM t_script_template WHERE tenant_id = @TENANT AND channel = 'PUSH'  AND status = 'ACTIVE') AS push_slots,  -- expect 7
       (SELECT COUNT(*) FROM t_script_template WHERE tenant_id = @TENANT AND channel = 'EMAIL' AND status = 'ACTIVE') AS email_slots, -- expect 5
       (SELECT COUNT(*) FROM t_contact_plan_template WHERE tenant_id = @TENANT AND status = 'ACTIVE') AS plan_templates, -- expect 5
       (SELECT current_version FROM t_config_version_seq WHERE id = 1) AS config_version;
